from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# LU factorization kernel (Doolittle, no pivoting).
# The computation is performed in-place on A.
@proc
def kernel_lu(
    n: size,
    A: DATA_TYPE[n, n] @ DRAM,
):
    # Loop over rows.
    for i in seq(0, n):
        # ------------------------------------------------------------------
        # 1) Compute the strictly lower-triangular part of row i (L factors).
        #    For each j < i we perform:
        #      A[i, j] = (A[i, j] - sum_{k=0..j-1} A[i, k] * A[k, j]) / A[j, j]
        # ------------------------------------------------------------------
        for j in seq(0, i):
