            # on A[i, j] inside the inner k-loop.
            acc: DATA_TYPE
            acc = A[i, j]

            for k in seq(0, j):
                acc += -A[i, k] * A[k, j]

            acc = acc / A[j, j]
            A[i, j] = acc

        # ------------------------------------------------------------------
        # 2) Compute the diagonal and upper-triangular part of row i (U factors).
        #    For each j >= i we perform:
        #      A[i, j] = A[i, j] - sum_{k=0..i-1} A[i, k] * A[k, j]
