/**
 * Exo LU driver: mirrors PolyBench/C lu.c but calls the Exo-generated kernel.
 */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "lu.h"

/* Include the Exo-generated kernel header. */
#include "generated/lu/lu.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  for (i = 0; i < n; i++)
    {
      for (j = 0; j <= i; j++)
	A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
      for (j = i+1; j < n; j++) {
	A[i][j] = 0;
      }
      A[i][i] = 1;
    }

  /* Make the matrix positive semi-definite. */
  /* not necessary for LU, but using same code as cholesky */
  int r,s,t;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);
  for (r = 0; r < n; ++r)
    for (s = 0; s < n; ++s)
      (POLYBENCH_ARRAY(B))[r][s] = 0;
  for (t = 0; t < n; ++t)
    for (r = 0; r < n; ++r)
      for (s = 0; s < n; ++s)
	(POLYBENCH_ARRAY(B))[r][s] += A[r][t] * A[s][t];
    for (r = 0; r < n; ++r)
      for (s = 0; s < n; ++s)
	A[r][s] = (POLYBENCH_ARRAY(B))[r][s];
  POLYBENCH_FREE_ARRAY(B);

}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.libs.memories import DRAM
from exo.API_scheduling import *
from exo.stdlib.stdlib import *  # helper transforms (not strictly required here)


# Baseline LU factorization kernel matching PolyBench semantics.
@proc
def kernel_lu_base(
    n: size,
    A: DATA_TYPE[n, n] @ DRAM,
):
    for i in seq(0, n):
        # Compute the L entries (below-diagonal part of row i).
        for j in seq(0, i):
            # A[i, j] -= sum_{k=0}^{j-1} A[i, k] * A[k, j]
            for k in seq(0, j):
                A[i, j] += -A[i, k] * A[k, j]
            # Final division to form L(i, j).
            A[i, j] = A[i, j] / A[j, j]

        # Update the U entries in row i (on and to the right of the diagonal).
        for j in seq(i, n):
            # A[i, j] -= sum_{k=0}^{i-1} A[i, k] * A[k, j]
            for k in seq(0, i):
                A[i, j] += -A[i, k] * A[k, j]


# ---------------------------------------------------------------------------
# Scheduling:
#
#  - We keep the mathematical algorithm intact, operating in-place on A.
#  - We focus on the trailing update (U update) where the bulk of work lives.
#  - Transformations:
#      1) Shift that j-loop to start at 0 to enable clean tiling.
#      2) Tile the shifted j-loop with a tunable tile size T_J.
#      3) Inside each tile, reorder the inner ji and k loops so that we:
#           * iterate over contiguous columns j for each fixed k
#           * access A[k, j] row-wise (unit-stride) instead of column-wise
#        This improves spatial locality and cache behavior for A[k, j].
#
#  All transformations preserve the lexicographic order of the (i, j) pair
#  and the set of updates to each A[i, j]. The reordering of ji and k
#  only changes the accumulation order of a reduction:
#      A[i, j] += -A[i, k] * A[k, j]
#  which is mathematically associative and commutative. Exo's effect system
#  treats this pattern as a valid reduction and allows such loop reorders.
# ---------------------------------------------------------------------------

p = kernel_lu_base

# 1) In the trailing update, the outer j-loop currently runs from i to n.
#    Shift it to start at 0 so we can tile it: j' = j - i.
j_trailing = p.find_loop("j #1")  # second 'j' loop inside the i-loop
p = shift_loop(p, j_trailing, "0")

# 2) Tile the shifted j-loop (now j in [0, n - i)) by a constant factor.
#    T_J is a tuning knob for the column-block size.
T_J = 32
j_trailing = p.find_loop("j #1")  # re-acquire after the previous transform
p = divide_loop(p, j_trailing, T_J, ["jo", "ji"], tail="guard")

# 3) Inside each j-tile, reorder ji and k so that we iterate
#    over contiguous columns for each fixed k (row-wise access to A[k, :]).
ji_loops = p.find_loop("ji", many=True)
# Main tile body
if len(ji_loops) >= 1:
    p = reorder_loops(p, ji_loops[0])
# Optional remainder (tail) tile, if it exists
if len(ji_loops) >= 2:
    p = reorder_loops(p, ji_loops[1])

# 4) Simplify to clean up index expressions introduced by tiling/shifting.
p = simplify(p)

# 5) Expose the scheduled kernel under the name expected by the C driver.
kernel_lu = rename(p, "kernel_lu")
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D view to 1D pointer. */
  kernel_lu (/*ctxt=*/NULL, n,
             (DATA_TYPE*)POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
